nt.getElementById('copy-status');if(!button||!status)return;button.addEventListener('click',async function(){const value=button.dataset.clabe||'';let copied=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(value);copied=true;}else{const field=document.createElement('textarea');field.value=value;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();copied=document.execCommand('copy');field.remove();}}catch(_){copied=false;}if(copied){status.textContent='CLABE copiada ✓';button.textContent='CLABE copiada ✓';setTimeout(function(){button.textContent='Copiar CLABE';},2200);}else{status.textContent='No se pudo copiar automáticamente. Mantén presionada la CLABE para copiarla.';}});})();</script><?php endif;?></body></html><?php
